ode']) ?></td><td><?= html_escape($r['Flag']) ?></td><td><?= html_escape($r['GrossTonnage']) ?></td><td><?= html_escape($r['VesselType']) ?></td><td><?= html_escape($r['MainTank']) ?></td><td><?= html_escape($r['DailyTank']) ?></td><td><span class="label label-<?= (int)$r['IsActive']?'success':'default' ?>"><?= (int)$r['IsActive']?'Aktif':'Nonaktif' ?></span><?php foreach($companies as $parent)if((int)$parent['CompanyID']===(int)$r['CompanyID']&&!(int)$parent['IsActive']): ?><br><small class="text-warning">Perusahaan nonaktif</small><?php endif; ?></td><td><div style="display:flex;gap:6px;white-space:nowrap"><a class="btn btn-primary btn-sm" href="<?= site_url('Pipeline_setup/master_edit/vessel/'.(int)$r['VesselID']) ?>">Edit</a><form method="post" action="<?= site_url('Pipeline_setup/master_status/vessel/'.(int)$r['VesselID']) ?>"><?php $this->load->view('pipeline/billing_token'); ?><input type="hidden" name="IsActive" value="<?= (int)$r['IsActive']?0:1 ?>"><button class="btn btn-sm btn-<?= (int)$r['IsActive']?'warning':'success' ?>"><?= (int)$r['IsActive']?'Nonaktifkan':'Aktifkan' ?></button></form></div></td></tr><?php endforeach;if(!$vessels): ?><tr><td colspan="11">Belum ada data.</td></tr><?php endif; ?></tbody></table></div></div></section></div>